"""Bulk-edit ``card_pack.bin`` (booster-pack membership + rarity) for Over the Nexus.

``card_pack.bin`` lives inside ``bin2.pac`` and holds one 8-byte row per card,
indexed by the same row index as ``card_prop.bin``.  ``card_name_e.bin`` shares
that row order too, but only once its empty (untranslated/unused) NUL-terminated
slots are dropped -- see :func:`_decode_card_names`.  The row layout and rarity
encoding are documented in
``otn_enhanced.rom.card_pack_codec`` (0=Common, 2=Ultra Rare, 3=Super Rare,
4=Rare).

This patch applies a curated set of edits from :data:`CHANGES` (keyed by card
name) and then enforces an invariant: no pack may lose the LAST card of a
rarity tier it had.  The ov10 generator (0x02155934 / 0x02155A68, KB
``cardpack.generator_pools``) pools a pack's cards by rarity and picks
``pool[rand % count]``, so a tier can grow freely (that only dilutes odds) but an
emptied tier divides by zero.  The patch raises :class:`ValueError` and writes
nothing if any tier would be emptied.
"""

from __future__ import annotations

import json

import ndspy.rom

from otn_enhanced.rom.card_pack_codec import RARITY_MAP, decode_card_pack, encode_card_pack
from otn_enhanced.data.card_stats import iter_paths
from otn_enhanced.rom.pac import build_modified_pac, parse_pac

SRC = "data/over_the_nexus/working/rom.nds"
OUT = "data/over_the_nexus/working/rom_test.nds"

# Editable row fields and their valid byte ranges.  Rarity fields accept only
# the values defined in the codec's RARITY_MAP; the rest are raw uint8.
_RARITY_VALUES = set(RARITY_MAP)
_EDITABLE_FIELDS: dict[str, set[int]] = {
    "rarity_1": _RARITY_VALUES,
    "rarity_2": _RARITY_VALUES,
    "pack_1": set(range(256)),
    "pack_2": set(range(256)),
}

# Rarity labels that count toward the per-pack invariant (everything except Common).
_RARE_LABELS = tuple(label for value, label in sorted(RARITY_MAP.items()) if value != 0)

# card name -> fields to set on that card's row (omit a field to leave it unchanged).
