def _decode_card_names(data: bytes) -> list[str]:
    """Decode ``card_name_e.bin`` into a positional list of names.

    The file is concatenated NUL-terminated strings, but it is NOT one slot per
    card row: most rows (untranslated / unused) decode to an empty string, and
    there are far more raw slots (10762) than rows in ``card_pack.bin`` /
    ``card_prop.bin`` (4305). Empty slots must be dropped so that ``names[i]``
    lines up with row ``i`` -- keeping them shifts every later index (verified
    against ``card_prop.bin``: raw slot 8 decodes to "Speed World 2", but its
    Spell-Card stats only match row 0 of card_prop, i.e. the 0th *non-empty*
    name).
    """
    names: list[str] = []
    for raw in data.split(b"\x00"):
        try:
            name = raw.decode("shift-jis")
        except UnicodeDecodeError:
            name = raw.decode("latin-1")
        if name:
            names.append(name)
    return names


def _build_name_to_index(names: list[str]) -> tuple[dict[str, int], set[str]]:
    """Map each unique card name to its row index, flagging duplicates as ambiguous.

    Returns ``(name_to_index, ambiguous_names)``.  Ambiguous names are excluded
    from the map so a typo'd or duplicated name can't silently target one row;
    each of their rows is addressable instead as ``"Name#k"`` (k = 0-based
    occurrence in row order), e.g. the alt arts ``"Dark Magician#0".."#3"``.
    """
    seen: dict[str, int] = {}
    ambiguous: set[str] = set()
    occurrences: dict[str, list[int]] = {}
    for i, name in enumerate(names):
        if not name:
            continue
        occurrences.setdefault(name, []).append(i)
        if name in seen:
            ambiguous.add(name)
        else:
            seen[name] = i
    name_to_idx = {name: idx for name, idx in seen.items() if name not in ambiguous}
    for name in ambiguous:
        for k, idx in enumerate(occurrences[name]):
            name_to_idx[f"{name}#{k}"] = idx
    return name_to_idx, ambiguous


def _validate_changes(changes: dict[str, dict[str, int]]) -> None:
    """Reject malformed field names or out-of-range values in *changes*."""
    for name, fields in changes.items():
        for key, value in fields.items():
            allowed = _EDITABLE_FIELDS.get(key)
            if allowed is None:
                raise ValueError(
                    f"{name!r}: unknown field {key!r} "
                    f"(allowed: {sorted(_EDITABLE_FIELDS)})"
                )
            if value not in allowed:
                raise ValueError(f"{name!r}: field {key!r} value {value} out of range")


def _apply_changes(
    rows: list[dict[str, int]],
    changes: dict[str, dict[str, int]],
    name_to_idx: dict[str, int],
    ambiguous: set[str],
) -> None:
    """Overwrite the named fields on each targeted row, in place."""
    for name, fields in changes.items():
        if name in ambiguous:
            raise ValueError(
                f"Card name {name!r} is ambiguous (appears more than once); "
                f"use {name + '#0'!r}, {name + '#1'!r}, ..."
            )
        idx = name_to_idx.get(name)
        if idx is None:
            raise ValueError(f"Card name {name!r} not found in card_name_e.bin")
        for key, value in fields.items():
            rows[idx][key] = value
        print(f"card_pack: {name} (row {idx}) -> {fields}")


def _rare_breakdown(json_text: str) -> dict[int, dict[str, int]]:
    """Return ``{pack_id: {rare_label: count}}`` for non-Common rarities only."""
    summary = json.loads(json_text).get("pack_summary", [])
    breakdown: dict[int, dict[str, int]] = {}
    for pack in summary:
        counts = pack.get("rarity_breakdown", {})
        rares = {label: counts.get(label, 0) for label in _RARE_LABELS}
        breakdown[pack["pack_id"]] = rares
    return breakdown


def assert_rare_counts_preserved(before_json: str, after_json: str) -> None:
    """Raise if any pack's non-empty rare tier became empty between the two decodes."""
    before = _rare_breakdown(before_json)
    after = _rare_breakdown(after_json)

    problems: list[str] = []
    for pack_id in sorted(set(before) | set(after)):
        b = before.get(pack_id, {})
        a = after.get(pack_id, {})
        for label in _RARE_LABELS:
            if b.get(label, 0) > 0 and a.get(label, 0) == 0:
                problems.append(
                    f"Pack {pack_id}: {label} expected {b.get(label, 0)} got {a.get(label, 0)}"
                )

    if problems:
        raise ValueError(
            "card_pack rare-count invariant violated:\n  " + "\n  ".join(problems)
        )


def main(src: str, out: str, *, unobtainable_only: bool = False) -> None:
    """Apply :data:`CHANGES` to ``card_pack.bin`` and write the patched ROM to *out*.

    CHANGES names are resolved against *src*'s card names (the ROM-hack's names).
    ``unobtainable_only`` limits the edits to cards that are in no pack in *src*
    (``pack_1 == 0`` and ``pack_2 == 0``) -- the vanilla+ half of the build.

    Aborts (raising :class:`ValueError`) before writing if the edits would empty
    any pack's Ultra Rare / Super Rare / Rare tier.
    """
    _validate_changes(CHANGES)

    rom = ndspy.rom.NintendoDSRom.fromFile(src)
    pac_path = next(
        (p for p in iter_paths(rom.filenames) if p.lower().endswith("bin2.pac")), None
    )
    if pac_path is None:
        raise ValueError("bin2.pac not found in ROM")

    fid = rom.filenames.idOf(pac_path)
    orig_pac = bytes(rom.files[fid])
    archive = parse_pac(orig_pac, pac_path)
    if not archive:
        raise ValueError(f"Could not parse PAC: {pac_path}")

    def _find(clean_name: str):
        for index, f in enumerate(archive.files):
            if f.get_clean_name().lower() == clean_name:
                return index, f
        raise ValueError(f"{clean_name} not found in {pac_path}")

    pack_idx, pack_file = _find("card_pack.bin")
    _, name_file = _find("card_name_e.bin")

    pack_bytes = orig_pac[pack_file.address : pack_file.address + pack_file.size]
    name_bytes = orig_pac[name_file.address : name_file.address + name_file.size]

    name_to_idx, ambiguous = _build_name_to_index(_decode_card_names(name_bytes))

    stock_json, meta = decode_card_pack(pack_bytes)
    payload = json.loads(stock_json)
    changes = CHANGES
    if unobtainable_only:
        rows = payload["rows"]
        changes = {n: f for n, f in CHANGES.items()
                   if n in name_to_idx and rows[name_to_idx[n]]["pack_1"] == 0
                   and rows[name_to_idx[n]]["pack_2"] == 0}
    _apply_changes(payload["rows"], changes, name_to_idx, ambiguous)

    # Encode the edited rows, then re-decode so the rare-count comparison runs
    # against a fresh pack_summary derived from the exact bytes we will write.
    new_pack_bytes = encode_card_pack(json.dumps(payload, ensure_ascii=False), meta)
    new_json, _ = decode_card_pack(new_pack_bytes)
    assert_rare_counts_preserved(stock_json, new_json)

    rom.files[fid] = build_modified_pac(orig_pac, pac_path, {pack_idx: new_pack_bytes})
    rom.saveToFile(out)
    print(f"card_pack: wrote {out} ({len(changes)} card(s) changed)")


if __name__ == "__main__":
    main(src=SRC, out=OUT)
